Write {"file_path":"D:\code\ESI.ts\tests\bdd\step-definitions\core\ui.steps.ts","content":"import { defineFeature, loadFeature } from 'jest-cucumber';
import { EsiClient } from '../../../../src/EsiClient';
import { EsiError } from '../../../../src/core/util/error';
import { TestDataFactory } from '../../../../src/testing/TestDataFactory';

const feature = loadFeature('tests/bdd/features/core/ui.feature');

defineFeature(feature, (test) => {
  let client: EsiClient;

  beforeEach(() => {
    client = new EsiClient({
      clientId: 'test-ui-client',
      baseUrl: 'https://esi.evetech.net',
      timeout: 5000,
    });
  });

  test('WHEN setAutopilotWaypoint is called, the client shall set the waypoint successfully', ({ given, when, then }) => {
    let result: any;
    const waypointBody = {
      destination_id: 30000142,
      add_to_beginning: false,
      clear_other_waypoints: false,
    };

    given('an authenticated character exists for waypoint', () => {
      jest
        .spyOn(client.ui, 'setAutopilotWaypoint')
        .mockResolvedValue(undefined);
    });

    when('setAutopilotWaypoint is called with a solar system destination', async () => {
      result = await client.ui.setAutopilotWaypoint(waypointBody);
    });

    then('the client shall set the waypoint successfully', () => {
      expect(result).toBeUndefined();
      expect(client.ui.setAutopilotWaypoint).toHaveBeenCalledWith(waypointBody);
    });
  });

  test('WHEN setAutopilotWaypoint is called with clear flag, the client shall clear existing waypoints', ({ given, when, then }) => {
    let result: any;
    const waypointBody = {
      destination_id: 30002187,
      add_to_beginning: false,
      clear_other_waypoints: true,
    };

    given('an authenticated character has existing waypoints', () => {
      jest
        .spyOn(client.ui, 'setAutopilotWaypoint')
        .mockResolvedValue(undefined);
    });

    when('setAutopilotWaypoint is called with clear other waypoints flag', async () => {
      result = await client.ui.setAutopilotWaypoint(waypointBody);
    });

    then('the client shall clear existing waypoints and set the new one', () => {
      expect(result).toBeUndefined();
      expect(client.ui.setAutopilotWaypoint).toHaveBeenCalledWith(
        expect.objectContaining({ clear_other_waypoints: true }),
      );
    });
  });

  test('WHEN openContractWindow is called, the client shall open the contract window', ({ given, when, then }) => {
    let result: any;
    const contractBody = {
      contract_id: 123456789,
    };

    given('an authenticated character exists for contracts', () => {
      jest.spyOn(client.ui, 'openContractWindow').mockResolvedValue(undefined);
    });

    when('openContractWindow is called with a contract ID', async () => {
      result = await client.ui.openContractWindow(contractBody);
    });

    then('the client shall open the contract window successfully', () => {
      expect(result).toBeUndefined();
      expect(client.ui.openContractWindow).toHaveBeenCalledWith(contractBody);
    });
  });

  test('WHEN openInformationWindow is called, the client shall display the information window', ({
    given,
    when,
    then,
  }) => {
    let result: any;
    const infoBody = {
      target_id: 1689391488,
    };

    given('an authenticated character exists for info window', () => {
      jest
        .spyOn(client.ui, 'openInformationWindow')
        .mockResolvedValue(undefined);
    });

    when('openInformationWindow is called with a target ID', async () => {
      result = await client.ui.openInformationWindow(infoBody);
    });

    then('the client shall display the information window successfully', () => {
      expect(result).toBeUndefined();
      expect(client.ui.openInformationWindow).toHaveBeenCalledWith(infoBody);
    });
  });

  test('WHEN openMarketDetailsWindow is called, the client shall display the market window', ({ given, when, then }) => {
    let result: any;
    const marketBody = {
      type_id: 34,
    };

    given('an authenticated character exists for market', () => {
      jest
        .spyOn(client.ui, 'openMarketDetailsWindow')
        .mockResolvedValue(undefined);
    });

    when('openMarketDetailsWindow is called with a type ID', async () => {
      result = await client.ui.openMarketDetailsWindow(marketBody);
    });

    then('the client shall display the market details window successfully', () => {
      expect(result).toBeUndefined();
      expect(client.ui.openMarketDetailsWindow).toHaveBeenCalledWith(
        marketBody,
      );
    });
  });

  test('WHEN openNewMailWindow is called, the client shall display the mail window with pre-filled data', ({
    given,
    when,
    then,
  }) => {
    let result: any;
    const mailBody = {
      recipients: [1689391488],
      subject: 'Fleet Operation Tonight',
      body: 'Join us at 20:00 UTC for a fleet op.',
    };

    given('an authenticated character exists for mail', () => {
      jest.spyOn(client.ui, 'openNewMailWindow').mockResolvedValue(undefined);
    });

    when('openNewMailWindow is called with recipients and content', async () => {
      result = await client.ui.openNewMailWindow(mailBody);
    });

    then('the client shall display the mail window with pre-filled data', () => {
      expect(result).toBeUndefined();
      expect(client.ui.openNewMailWindow).toHaveBeenCalledWith(mailBody);
    });
  });

  test('IF the user is unauthorized, THEN the client shall throw an EsiError with status 403 for waypoint', ({
    given,
    when,
    then,
  }) => {
    let caughtError: any;

    given('an unauthenticated user attempts waypoint access', () => {
      const forbiddenError = TestDataFactory.createError(403);

      jest
        .spyOn(client.ui, 'setAutopilotWaypoint')
        .mockRejectedValue(forbiddenError);
    });

    when('setAutopilotWaypoint is called without authorization', async () => {
      try {
        await client.ui.setAutopilotWaypoint({ destination_id: 30000142 });
      } catch (e) {
        caughtError = e;
      }
    });

    then('the client shall throw an EsiError with status 403 for waypoint', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });

  test('IF the user is unauthorized, THEN the client shall throw an EsiError with status 403 for contract', ({
    given,
    when,
    then,
  }) => {
    let caughtError: any;

    given('an unauthenticated user attempts contract access', () => {
      const forbiddenError = TestDataFactory.createError(403);

      jest
        .spyOn(client.ui, 'openContractWindow')
        .mockRejectedValue(forbiddenError);
    });

    when('openContractWindow is called without authorization', async () => {
      try {
        await client.ui.openContractWindow({ contract_id: 123456789 });
      } catch (e) {
        caughtError = e;
      }
    });

    then('the client shall throw an EsiError with status 403 for contract', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });

  test('WHEN multiple UI operations are performed concurrently, the client shall complete all successfully', ({
    given,
    when,
    then,
  }) => {
    let results: any[];

    given('an authenticated character exists for concurrent operations', () => {
      jest
        .spyOn(client.ui, 'setAutopilotWaypoint')
        .mockResolvedValue(undefined);
      jest.spyOn(client.ui, 'openContractWindow').mockResolvedValue(undefined);
      jest
        .spyOn(client.ui, 'openInformationWindow')
        .mockResolvedValue(undefined);
      jest
        .spyOn(client.ui, 'openMarketDetailsWindow')
        .mockResolvedValue(undefined);
      jest.spyOn(client.ui, 'openNewMailWindow').mockResolvedValue(undefined);
    });

    when('multiple UI operations are performed concurrently', async () => {
      results = await Promise.all([
        client.ui.setAutopilotWaypoint({ destination_id: 30000142 }),
        client.ui.openContractWindow({ contract_id: 123456789 }),
        client.ui.openInformationWindow({ target_id: 1689391488 }),
        client.ui.openMarketDetailsWindow({ type_id: 34 }),
        client.ui.openNewMailWindow({
          recipients: [1689391488],
          subject: 'Test',
          body: 'Test body',
        }),
      ]);
    });

    then('the client shall complete all UI operations successfully', () => {
      expect(results).toHaveLength(5);
      results.forEach((result) => {
        expect(result).toBeUndefined();
      });

      expect(client.ui.setAutopilotWaypoint).toHaveBeenCalledTimes(1);
      expect(client.ui.openContractWindow).toHaveBeenCalledTimes(1);
      expect(client.ui.openInformationWindow).toHaveBeenCalledTimes(1);
      expect(client.ui.openMarketDetailsWindow).toHaveBeenCalledTimes(1);
      expect(client.ui.openNewMailWindow).toHaveBeenCalledTimes(1);
    });
  });
});
"}

